-- Keep this statement identical to DeliveryCompletionSchemaReady; static tests compare it.
DO $$ BEGIN
 IF NOT (SELECT EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid JOIN pg_catalog.pg_am a ON a.oid=c.relam WHERE i.indrelid=to_regclass('delivery_completion_authorization') AND c.relname='delivery_completion_id_idx' AND a.amname='btree' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisexclusion AND i.indpred IS NULL AND i.indexprs IS NULL AND i.indnkeyatts=1 AND i.indnatts=1 AND i.indoption::text='0' AND pg_get_indexdef(i.indexrelid,1,true)='id') AND
EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid JOIN pg_catalog.pg_am a ON a.oid=c.relam WHERE i.indrelid=to_regclass('delivery_completion_authorization') AND c.relname='delivery_completion_request_idx' AND a.amname='btree' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisexclusion AND i.indpred IS NULL AND i.indexprs IS NULL AND i.indnkeyatts=3 AND i.indnatts=3 AND i.indoption::text='0 0 0' AND pg_get_indexdef(i.indexrelid,1,true)='workspace_id' AND pg_get_indexdef(i.indexrelid,2,true)='issuer_user_id' AND pg_get_indexdef(i.indexrelid,3,true)='request_key') AND
EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid JOIN pg_catalog.pg_am a ON a.oid=c.relam WHERE i.indrelid=to_regclass('delivery_completion_authorization') AND c.relname='delivery_completion_operation_idx' AND a.amname='btree' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisexclusion AND i.indpred IS NULL AND i.indexprs IS NULL AND i.indnkeyatts=2 AND i.indnatts=2 AND i.indoption::text='0 0' AND pg_get_indexdef(i.indexrelid,1,true)='workspace_id' AND pg_get_indexdef(i.indexrelid,2,true)='operation_id') AND
EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid JOIN pg_catalog.pg_am a ON a.oid=c.relam WHERE i.indrelid=to_regclass('delivery_completion_terminal') AND c.relname='delivery_completion_terminal_id_idx' AND a.amname='btree' AND i.indisunique AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisexclusion AND i.indpred IS NULL AND i.indexprs IS NULL AND i.indnkeyatts=1 AND i.indnatts=1 AND i.indoption::text='0' AND pg_get_indexdef(i.indexrelid,1,true)='authorization_id') AND
EXISTS (SELECT 1 FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid JOIN pg_catalog.pg_am a ON a.oid=c.relam WHERE i.indrelid=to_regclass('delivery_completion_authorization') AND c.relname='delivery_completion_candidate_idx' AND a.amname='btree' AND NOT i.indisunique AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisexclusion AND i.indpred IS NULL AND i.indexprs IS NULL AND i.indnkeyatts=7 AND i.indnatts=7 AND i.indoption::text='0 0 0 0 0 0 0' AND pg_get_indexdef(i.indexrelid,1,true)='workspace_id' AND pg_get_indexdef(i.indexrelid,2,true)='issue_id' AND pg_get_indexdef(i.indexrelid,3,true)='issue_revision' AND pg_get_indexdef(i.indexrelid,4,true)='policy_revision' AND pg_get_indexdef(i.indexrelid,5,true)='consumer_kind' AND pg_get_indexdef(i.indexrelid,6,true)='integration_id' AND pg_get_indexdef(i.indexrelid,7,true)='pull_request_id') AND
NOT EXISTS (
 SELECT 1 FROM (VALUES
  ('delivery_completion_authorization','704a6853655d394581320121088cbf1f','c4c16ac55aaa92f609f290e34b6fa277'),
  ('delivery_completion_terminal','a01a42c844daaa1ea1033604317d1a3b','32ff77e79e3daca3c23d4a98dd352b5c')
 ) AS expected(table_name, columns_digest, checks_digest)
 WHERE (SELECT md5(string_agg(a.attname||'|'||format_type(a.atttypid,a.atttypmod)||'|'||a.attnotnull::text||'|'||COALESCE(pg_get_expr(d.adbin,d.adrelid),''), E'\n' ORDER BY a.attnum))
        FROM pg_catalog.pg_attribute a LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
        WHERE a.attrelid=to_regclass(expected.table_name) AND a.attnum>0 AND NOT a.attisdropped) IS DISTINCT FROM expected.columns_digest
    OR (SELECT md5(string_agg(k.conname||'|'||pg_get_constraintdef(k.oid), E'\n' ORDER BY k.conname))
        FROM pg_catalog.pg_constraint k WHERE k.conrelid=to_regclass(expected.table_name) AND k.contype='c' AND k.convalidated) IS DISTINCT FROM expected.checks_digest
    OR EXISTS (SELECT 1 FROM pg_catalog.pg_constraint k WHERE k.conrelid=to_regclass(expected.table_name) AND k.contype='c' AND NOT k.convalidated)
)) THEN RAISE EXCEPTION 'delivery completion schema unavailable'; END IF;
END; $$;
